INSERT INTO memories (id, user_id, body, happened_on, happened_on_precision, photo_key, photo_content_type, created_at, updated_at) VALUES
  ('s20_0404', 'demo@example.com', '今日、離婚届を出した。信じていた人に裏切られて、まだ何も考えられない。とりあえず、ここに書いておく。', '2020-04-04', 'day', NULL, NULL, '2020-04-04T14:40:00.000Z', '2020-04-04T14:40:00.000Z'),
  ('s20_0410', 'demo@example.com', '仕事。何をしていても頭に入ってこない。帰りにコンビニの弁当。', '2020-04-10', 'day', NULL, NULL, '2020-04-10T13:15:00.000Z', '2020-04-10T13:15:00.000Z'),
  ('s20_0416', 'demo@example.com', '休み。一日中ドラマを見ていた。気づいたら外が暗かった。', '2020-04-16', 'day', NULL, NULL, '2020-04-16T12:05:00.000Z', '2020-04-16T12:05:00.000Z'),
  ('s20_0422', 'demo@example.com', '眠れない夜が続く。朝、鏡に映った自分の顔がひどかった。', '2020-04-22', 'day', NULL, NULL, '2020-04-21T17:10:00.000Z', '2020-04-21T17:10:00.000Z'),
  ('s20_0428', 'demo@example.com', '仕事。先輩に「顔色わるいぞ」と言われた。大丈夫です、と答えた。', '2020-04-28', 'day', NULL, NULL, '2020-04-28T13:40:00.000Z', '2020-04-28T13:40:00.000Z'),
  ('s20_0504', 'demo@example.com', '連休。ドラマを3話。主人公が泣く場面で、自分も少し泣いた。', '2020-05-04', 'day', NULL, NULL, '2020-05-04T11:30:00.000Z', '2020-05-04T11:30:00.000Z'),
  ('s20_0510', 'demo@example.com', '部屋の片づけ。前に二人で買った食器を、箱に詰めた。', '2020-05-10', 'day', NULL, NULL, '2020-05-10T10:50:00.000Z', '2020-05-10T10:50:00.000Z'),
  ('s20_0516', 'demo@example.com', '仕事。久しぶりに定時で帰れた。夕方の空がきれいだった。', '2020-05-16', 'day', NULL, NULL, '2020-05-16T09:45:00.000Z', '2020-05-16T09:45:00.000Z'),
  ('s20_0522', 'demo@example.com', '休み。ドラマの続き。洗濯物をためすぎた。', '2020-05-22', 'day', NULL, NULL, '2020-05-22T12:20:00.000Z', '2020-05-22T12:20:00.000Z'),
  ('s20_0528', 'demo@example.com', '先輩とラーメン。何も聞かずに、替え玉をおごってくれた。', '2020-05-28', 'day', NULL, NULL, '2020-05-28T14:05:00.000Z', '2020-05-28T14:05:00.000Z'),
  ('s20_0603', 'demo@example.com', '仕事で大きなミスをした。帰り道、何もかも嫌になった。', '2020-06-03', 'day', NULL, NULL, '2020-06-03T14:55:00.000Z', '2020-06-03T14:55:00.000Z'),
  ('s20_0609', 'demo@example.com', '休み。ドラマを最終話まで見た。終わってしまうと、少しさみしい。', '2020-06-09', 'day', NULL, NULL, '2020-06-09T13:00:00.000Z', '2020-06-09T13:00:00.000Z'),
  ('s20_0615', 'demo@example.com', '少しだけ、眠れるようになってきた。', '2020-06-15', 'day', NULL, NULL, '2020-06-15T14:10:00.000Z', '2020-06-15T14:10:00.000Z'),
  ('s20_0621', 'demo@example.com', '雨。部屋でドラマとカップ麺。', '2020-06-21', 'day', NULL, NULL, '2020-06-21T11:15:00.000Z', '2020-06-21T11:15:00.000Z'),
  ('s20_0627', 'demo@example.com', '仕事。月末でばたばた。先輩が缶コーヒーをくれた。', '2020-06-27', 'day', NULL, NULL, '2020-06-27T13:35:00.000Z', '2020-06-27T13:35:00.000Z'),
  ('s20_0712', 'demo@example.com', '思い立ってレンタカーを借りて、ひとりで山の上の展望台まで走った。街が小さく見えた。ここから、もう一回やってみようと思った。', '2020-07-12', 'day', NULL, NULL, '2020-07-12T10:30:00.000Z', '2020-07-12T10:30:00.000Z'),
  ('s20_1231', 'demo@example.com', 'ひとりの年越し。そばをゆでて食べた。来年は、少しでも笑えていたらいい。', '2020-12-31', 'day', NULL, NULL, '2020-12-31T14:50:00.000Z', '2020-12-31T14:50:00.000Z'),
  ('s21_0514', 'demo@example.com', '仕事に慣れてきて、後輩に教えることが増えた。', '2021-05-14', 'day', NULL, NULL, '2021-05-14T12:40:00.000Z', '2021-05-14T12:40:00.000Z'),
  ('s21_1003', 'demo@example.com', '休み。ひさしぶりに映画館へ。ひとりでも、悪くない。', '2021-10-03', 'day', NULL, NULL, '2021-10-03T11:10:00.000Z', '2021-10-03T11:10:00.000Z'),
  ('s22_0115', 'demo@example.com', '友だちの集まりで、みさきという人に会った。話していたら、時間があっという間だった。', '2022-01-15', 'day', NULL, NULL, '2022-01-15T14:30:00.000Z', '2022-01-15T14:30:00.000Z'),
  ('s22_0129', 'demo@example.com', 'みさきとカフェへ。好きなドラマが同じだった。', '2022-01-29', 'day', NULL, NULL, '2022-01-29T12:15:00.000Z', '2022-01-29T12:15:00.000Z'),
  ('s22_0214', 'demo@example.com', 'みさきからチョコをもらった。手作りだった。', '2022-02-14', 'day', NULL, NULL, '2022-02-14T13:05:00.000Z', '2022-02-14T13:05:00.000Z'),
  ('s22_0305', 'demo@example.com', 'みさきと付き合うことになった。帰り道、ずっと顔がゆるんでいた。', '2022-03-05', 'day', NULL, NULL, '2022-03-05T14:45:00.000Z', '2022-03-05T14:45:00.000Z'),
  ('s22_0409', 'demo@example.com', 'みさきと川沿いの桜を見に行った。「来年も来ようね」と言われた。', '2022-04-09', 'day', NULL, NULL, '2022-04-09T12:00:00.000Z', '2022-04-09T12:00:00.000Z'),
  ('s22_0503', 'demo@example.com', '二人で初めての旅行。金沢。市場で食べた海鮮丼が忘れられない。', '2022-05-03', 'day', NULL, NULL, '2022-05-03T13:20:00.000Z', '2022-05-03T13:20:00.000Z'),
  ('s22_0618', 'demo@example.com', 'みさきが「雨の日のにおいが好き」と言っていた。', '2022-06-18', 'day', NULL, NULL, '2022-06-18T11:40:00.000Z', '2022-06-18T11:40:00.000Z'),
  ('s22_0811', 'demo@example.com', '海へ。みさきが日焼け止めを塗り忘れて、肩が真っ赤になった。', '2022-08-11', 'day', NULL, NULL, '2022-08-11T12:35:00.000Z', '2022-08-11T12:35:00.000Z'),
  ('s22_0923', 'demo@example.com', 'みさきの誕生日。ネックレスをあげたら、泣いて喜んでくれた。', '2022-09-23', 'day', NULL, NULL, '2022-09-23T13:50:00.000Z', '2022-09-23T13:50:00.000Z'),
  ('s22_1126', 'demo@example.com', 'みさきと京都へ紅葉を見に。人が多くて、はぐれかけた。', '2022-11-26', 'day', NULL, NULL, '2022-11-26T12:25:00.000Z', '2022-11-26T12:25:00.000Z'),
  ('s22_1224', 'demo@example.com', 'クリスマス。二人で鍋。みさきは白菜ばかり食べていた。', '2022-12-24', 'day', NULL, NULL, '2022-12-24T13:10:00.000Z', '2022-12-24T13:10:00.000Z'),
  ('s23_0108', 'demo@example.com', '二人で住む部屋を探しはじめた。', '2023-01-08', 'day', NULL, NULL, '2023-01-08T11:55:00.000Z', '2023-01-08T11:55:00.000Z'),
  ('s23_0211', 'demo@example.com', '内見の3件目。川沿いの2LDK。窓から桜並木が見える。ここがいい、と二人とも思った。', '2023-02-11', 'day', NULL, NULL, '2023-02-11T10:40:00.000Z', '2023-02-11T10:40:00.000Z'),
  ('s23_0225', 'demo@example.com', '部屋の契約をした。ハンコを押す手が、少しふるえた。', '2023-02-25', 'day', NULL, NULL, '2023-02-25T12:10:00.000Z', '2023-02-25T12:10:00.000Z'),
  ('s23_0401', 'demo@example.com', '車を決めた。青いコンパクトカー。みさきが色で即決した。', '2023-04-01', 'day', NULL, NULL, '2023-04-01T11:20:00.000Z', '2023-04-01T11:20:00.000Z'),
  ('s23_0415', 'demo@example.com', '納車。最初のドライブは、近所のスーパーまで。', '2023-04-15', 'day', NULL, NULL, '2023-04-15T09:30:00.000Z', '2023-04-15T09:30:00.000Z'),
  ('s23_0503', 'demo@example.com', '引っ越し。段ボールの山の中で、二人でコンビニのおにぎりを食べた。', '2023-05-03', 'day', NULL, NULL, '2023-05-03T13:45:00.000Z', '2023-05-03T13:45:00.000Z'),
  ('s23_0520', 'demo@example.com', '新しい部屋の窓から、川沿いを走る人が見える。休みの朝が好きになった。', '2023-05-20', 'day', NULL, NULL, '2023-05-20T00:15:00.000Z', '2023-05-20T00:15:00.000Z'),
  ('s23_0716', 'demo@example.com', 'みさきの実家へ。お父さんと二人で飲んだ。ずっと緊張していた。', '2023-07-16', 'day', NULL, NULL, '2023-07-16T14:20:00.000Z', '2023-07-16T14:20:00.000Z'),
  ('s23_0923', 'demo@example.com', 'みさきの誕生日。今年はマグカップ。毎朝使ってくれている。', '2023-09-23', 'day', NULL, NULL, '2023-09-23T13:00:00.000Z', '2023-09-23T13:00:00.000Z'),
  ('s23_1014', 'demo@example.com', 'みさきと指輪を見に行った。選んだのは、思っていたより細いものだった。', '2023-10-14', 'day', NULL, NULL, '2023-10-14T12:30:00.000Z', '2023-10-14T12:30:00.000Z'),
  ('s23_1122', 'demo@example.com', 'あの山の上の展望台で、みさきにプロポーズした。「はい」のあと、二人で笑いすぎて泣いた。', '2023-11-22', 'day', NULL, NULL, '2023-11-22T14:15:00.000Z', '2023-11-22T14:15:00.000Z'),
  ('s23_1224', 'demo@example.com', 'クリスマス。両家の顔合わせの日取りが決まった。', '2023-12-24', 'day', NULL, NULL, '2023-12-24T12:45:00.000Z', '2023-12-24T12:45:00.000Z'),
  ('s24_0222', 'demo@example.com', 'みさきと婚姻届を出した。4年前、別の紙を出した役所で。今日は、ちゃんと笑えた。', '2024-02-22', 'day', NULL, NULL, '2024-02-22T11:35:00.000Z', '2024-02-22T11:35:00.000Z'),
  ('s24_0518', 'demo@example.com', '小さな結婚式。先輩がスピーチの途中で泣いていた。', '2024-05-18', 'day', NULL, NULL, '2024-05-18T14:00:00.000Z', '2024-05-18T14:00:00.000Z'),
  ('s24_0707', 'demo@example.com', '七夕の夜、みさきが「赤ちゃんができたみたい」と言った。', '2024-07-07', 'day', NULL, NULL, '2024-07-07T14:40:00.000Z', '2024-07-07T14:40:00.000Z'),
  ('s24_0824', 'demo@example.com', 'エコーの写真をもらった。小さな豆みたいだった。', '2024-08-24', 'day', NULL, NULL, '2024-08-24T10:20:00.000Z', '2024-08-24T10:20:00.000Z'),
  ('s24_1001', 'demo@example.com', '転職した。ITの会社。知らない言葉ばかりで、メモが追いつかない。', '2024-10-01', 'day', NULL, NULL, '2024-10-01T13:30:00.000Z', '2024-10-01T13:30:00.000Z'),
  ('s24_1020', 'demo@example.com', '新しい職場。毎日が勉強。帰ってからも本を読んでいる。', '2024-10-20', 'day', NULL, NULL, '2024-10-20T12:50:00.000Z', '2024-10-20T12:50:00.000Z'),
  ('s24_1214', 'demo@example.com', 'みさきのお腹が大きくなって、靴下をはくのが大変そう。かわりにはかせた。', '2024-12-14', 'day', NULL, NULL, '2024-12-14T12:05:00.000Z', '2024-12-14T12:05:00.000Z'),
  ('s24_1224', 'demo@example.com', 'クリスマス。みさきに手袋をあげた。来年は三人だね、と話した。', '2024-12-24', 'day', NULL, NULL, '2024-12-24T13:25:00.000Z', '2024-12-24T13:25:00.000Z'),
  ('s25_0119', 'demo@example.com', 'そらが生まれた。3,012グラム。小さな手が、ぼくの指をにぎった。', '2025-01-19', 'day', NULL, NULL, '2025-01-19T06:10:00.000Z', '2025-01-19T06:10:00.000Z'),
  ('s25_0201', 'demo@example.com', '夜泣き。みさきと、かわりばんこで抱っこ。', '2025-02-01', 'day', NULL, NULL, '2025-01-31T18:20:00.000Z', '2025-01-31T18:20:00.000Z'),
  ('s25_0215', 'demo@example.com', '初めての沐浴。こわくて、肩に力が入りすぎた。', '2025-02-15', 'day', NULL, NULL, '2025-02-15T11:45:00.000Z', '2025-02-15T11:45:00.000Z'),
  ('s25_0322', 'demo@example.com', 'そらが初めて笑った。たぶん、気のせいじゃない。', '2025-03-22', 'day', NULL, NULL, '2025-03-22T12:30:00.000Z', '2025-03-22T12:30:00.000Z'),
  ('s25_0405', 'demo@example.com', 'ベビーカーで、川沿いの桜並木を歩いた。そらは途中で寝てしまった。', '2025-04-05', 'day', NULL, NULL, '2025-04-05T08:50:00.000Z', '2025-04-05T08:50:00.000Z'),
  ('s25_0517', 'demo@example.com', 'そらが寝返りをした。みさきと二人で拍手した。', '2025-05-17', 'day', NULL, NULL, '2025-05-17T11:10:00.000Z', '2025-05-17T11:10:00.000Z'),
  ('s25_0612', 'demo@example.com', '仕事で、初めて自分の書いたコードが本番に出た。', '2025-06-12', 'day', NULL, NULL, '2025-06-12T13:40:00.000Z', '2025-06-12T13:40:00.000Z'),
  ('s25_0719', 'demo@example.com', '離乳食。にんじんを、全部口から出された。', '2025-07-19', 'day', NULL, NULL, '2025-07-19T10:05:00.000Z', '2025-07-19T10:05:00.000Z'),
  ('s25_0830', 'demo@example.com', 'そらがはいはい。目を離すと、もうキッチンにいる。', '2025-08-30', 'day', NULL, NULL, '2025-08-30T12:15:00.000Z', '2025-08-30T12:15:00.000Z'),
  ('s25_0923', 'demo@example.com', 'みさきの誕生日。そらと一緒にケーキを買った。', '2025-09-23', 'day', NULL, NULL, '2025-09-23T12:40:00.000Z', '2025-09-23T12:40:00.000Z'),
  ('s25_1012', 'demo@example.com', 'みさきと、そらの寝顔を見ながら「どっちに似てるかな」と話した。', '2025-10-12', 'day', NULL, NULL, '2025-10-12T13:05:00.000Z', '2025-10-12T13:05:00.000Z'),
  ('s25_1108', 'demo@example.com', 'そらがつかまり立ちした。テーブルの角で。みさきと二人で「立った！」と大声を出した。', '2025-11-08', 'day', NULL, NULL, '2025-11-08T11:30:00.000Z', '2025-11-08T11:30:00.000Z'),
  ('s25_1224', 'demo@example.com', 'クリスマス。みさきにマフラー。そらには木のおもちゃ。', '2025-12-24', 'day', NULL, NULL, '2025-12-24T13:15:00.000Z', '2025-12-24T13:15:00.000Z'),
  ('s26_0119', 'demo@example.com', 'そら、1歳。一升餅を背負って、すぐ座りこんだ。', '2026-01-19', 'day', NULL, NULL, '2026-01-19T11:50:00.000Z', '2026-01-19T11:50:00.000Z'),
  ('s26_0215', 'demo@example.com', 'そらが歩いた。3歩。みさきが動画を撮りそびれた。', '2026-02-15', 'day', NULL, NULL, '2026-02-15T10:35:00.000Z', '2026-02-15T10:35:00.000Z'),
  ('s26_0308', 'demo@example.com', 'そらが「パパ」と言った。たぶん。', '2026-03-08', 'day', NULL, NULL, '2026-03-08T12:20:00.000Z', '2026-03-08T12:20:00.000Z'),
  ('s26_0401', 'demo@example.com', '保育園の初日。ぼくのほうが泣きそうだった。', '2026-04-01', 'day', NULL, NULL, '2026-04-01T13:30:00.000Z', '2026-04-01T13:30:00.000Z'),
  ('s26_0516', 'demo@example.com', '車がパンクした。乗りはじめて3年。高速の上じゃなくてよかった。', '2026-05-16', 'day', NULL, NULL, '2026-05-16T09:40:00.000Z', '2026-05-16T09:40:00.000Z'),
  ('s26_0607', 'demo@example.com', 'みさきに「最近ちゃんと寝てる？」と聞かれた。', '2026-06-07', 'day', NULL, NULL, '2026-06-07T14:30:00.000Z', '2026-06-07T14:30:00.000Z'),
  ('s26_0712', 'demo@example.com', '仕事で、Claude Code を使いはじめた。できることが一気に増えた。', '2026-07-12', 'day', NULL, NULL, '2026-07-12T13:50:00.000Z', '2026-07-12T13:50:00.000Z'),
  ('s26_0830', 'demo@example.com', '三人で雑貨屋へ。みさきが「このガラスのコップ、いいな」と言っていた。', '2026-08-30', 'day', NULL, NULL, '2026-08-30T11:05:00.000Z', '2026-08-30T11:05:00.000Z'),
  ('s26_0920', 'demo@example.com', 'みさきの誕生日。そらが、ぐちゃぐちゃのお絵かきを渡していた。', '2026-09-20', 'day', NULL, NULL, '2026-09-20T12:10:00.000Z', '2026-09-20T12:10:00.000Z'),
  ('s26_1018', 'demo@example.com', 'そらと公園。どんぐりを3つ、ポケットに入れて帰ってきた。', '2026-10-18', 'day', NULL, NULL, '2026-10-18T08:25:00.000Z', '2026-10-18T08:25:00.000Z'),
  ('s26_1025', 'demo@example.com', 'Claude のハッカソンがあると知った。出てみたい。', '2026-10-25', 'day', NULL, NULL, '2026-10-25T14:05:00.000Z', '2026-10-25T14:05:00.000Z'),
  ('s26_1103', 'demo@example.com', 'ハッカソン初日。作りたいのは、書いたひとことから昔の記憶が返ってくるアプリ。', '2026-11-03', 'day', NULL, NULL, '2026-11-03T14:40:00.000Z', '2026-11-03T14:40:00.000Z'),
  ('s26_1104', 'demo@example.com', 'ハッカソン2日目。名前は「そういえば。」にした。', '2026-11-04', 'day', NULL, NULL, '2026-11-04T14:55:00.000Z', '2026-11-04T14:55:00.000Z'),
  ('s26_1106', 'demo@example.com', 'みさきに、作っているアプリを見せた。「わたしも使いたい」と言われた。', '2026-11-06', 'day', NULL, NULL, '2026-11-06T13:20:00.000Z', '2026-11-06T13:20:00.000Z');
