INSERT INTO recalls (id, memory_id, related_memory_id, reason, evidence, feedback, created_at) VALUES
  ('sr_01', 's23_1122', 's20_0712', 'プロポーズした展望台は、ひとりで車を走らせて、もう一回やってみようと思えた場所です。', 'ここから、もう一回やってみようと思った。', 'helpful', '2023-11-22T14:15:05.000Z'),
  ('sr_02', 's24_0222', 's20_0404', '4年前にひとりで紙を出したあの日から、今日はふたりで笑える日になりました。', 'とりあえず、ここに書いておく。', 'helpful', '2024-02-22T11:35:05.000Z'),
  ('sr_03', 's25_0405', 's23_0211', '内見の日に窓から見えた桜並木を、今年はそらと歩いています。', '窓から桜並木が見える。', 'none', '2025-04-05T08:50:05.000Z'),
  ('sr_04', 's26_0516', 's23_0401', 'みさきが色で決めた青い車と、乗りはじめて3年になります。', 'みさきが色で即決した。', 'none', '2026-05-16T09:40:05.000Z'),
  ('sr_05', 's25_0119', 's24_0707', '七夕の夜に知らせてくれた赤ちゃんに、今日会えました。', 'みさきが「赤ちゃんができたみたい」と言った。', 'helpful', '2025-01-19T06:10:05.000Z'),
  ('sr_06', 's25_1224', 's24_1224', '去年のクリスマスは手袋で、「来年は三人だね」と話していました。', '来年は三人だね、と話した。', 'none', '2025-12-24T13:15:05.000Z');
